const rodSource =
  'https://www.unicode.org/versions/Unicode17.0.0/core-spec/chapter-22/ · §22.3.8 Song-period orientation; original geometric drawings';
const suzhouSource =
  'https://www.unicode.org/L2/L2023/23281-cjk-symbols-github-update.pdf · original monoline drawings of documented Suzhou forms';
const line = (d: string) => ({ d, weight: 4.2 });

// Brahmi's first three signs are stacked horizontal marks, drawn to the master stroke.
for (let n = 1; n <= 3; n++) {
  asiaGlyphs[`brahmi-${n}`] = {
    label: `Brahmi ${n}`,
    unicode: String.fromCodePoint(0x11051 + n),
    paths: Array.from({ length: n }, (_, i) => line(`M24 ${50 + (i - (n - 1) / 2) * 17}H76`)),
    source:
      'https://www.unicode.org/charts/PDF/U11000.pdf · U+11052–U+11054; original geometric drawings',
    provenance: 'original',
  };
}

// Unit forms are HORIZONTAL (Unicode/Song); tens forms are VERTICAL.
// For six through nine the five-bar is perpendicular to the remaining rods.
for (let n = 1; n <= 9; n++) {
  const units =
    n <= 5
      ? Array.from({ length: n }, (_, i) => line(`M24 ${50 + (i - (n - 1) / 2) * 11}H76`))
      : [
          line('M50 20V42'),
          ...Array.from({ length: n - 5 }, (_, i) => line(`M24 ${42 + i * 11}H76`)),
        ];
  const tens =
    n <= 5
      ? Array.from({ length: n }, (_, i) => line(`M${50 + (i - (n - 1) / 2) * 11} 24V76`))
      : [
          line('M24 28H76'),
          ...Array.from({ length: n - 5 }, (_, i) => line(`M${50 + (i - (n - 6) / 2) * 12} 28V76`)),
        ];
  asiaGlyphs[`rods-unit-${n}`] = {
    label: `Counting rods unit ${n}`,
    paths: units,
    unicode: String.fromCodePoint(0x1d35f + n),
    source: rodSource,
    provenance: 'original',
  };
  asiaGlyphs[`rods-tens-${n}`] = {
    label: `Counting rods tens ${n}`,
    paths: tens,
    unicode: String.fromCodePoint(0x1d368 + n),
    source: rodSource,
    provenance: 'original',
  };
}
asiaGlyphs['rods-zero'] = {
  label: 'Empty counting-board cell: zero',
  paths: [],
  source: rodSource,
  provenance: 'original',
};

