// Educational, count-faithful wedge clusters. Cells separate sexagesimal places;
// a blank cell is deliberately not supplied with an invented zero character.
const babylonianSource =
  'https://personal.math.ubc.ca/~cass/Euclid/ybc/analysis.html · original schematic wedge drawings, not a tracing of the tablet';
const unitWedge = (x: number, y: number, s = 1) =>
  `M${x - 5 * s} ${y}L${x + 5 * s} ${y}L${x + 1.5 * s} ${y + 8 * s}L${x + 0.8 * s} ${y + 19 * s}L${x - 0.8 * s} ${y + 19 * s}L${x - 1.5 * s} ${y + 8 * s}Z`;
const tenWedge = (x: number, y: number, s = 1) =>
  `M${x + 7 * s} ${y - 8 * s}L${x - 6 * s} ${y}L${x + 7 * s} ${y + 8 * s}L${x + 3 * s} ${y}Z`;
for (let n = 0; n < 60; n++) {
  const tens = Math.floor(n / 10),
    ones = n % 10;
  const paths: { d: string; fill: boolean }[] = [];
  if (n > 0) {
    const both = tens > 0 && ones > 0;
    const tenStart = both ? 17 : 40;
    const oneStart = both ? 59 : 36;
    for (let i = 0; i < tens; i++) {
      const cols = tens > 3 ? 2 : 1;
      const rows = Math.ceil(tens / cols);
      const x = tenStart + (i % cols) * 15;
      const y = 50 + (Math.floor(i / cols) - (rows - 1) / 2) * 20;
      paths.push({ d: tenWedge(x, y), fill: true });
    }
    const cols = ones <= 3 ? ones : 3,
      rows = Math.ceil(ones / 3);
    for (let i = 0; i < ones; i++) {
      const x = oneStart + ((i % 3) - (cols - 1) / 2) * 12 + (both ? 12 : 14);
      const y = 40 + (Math.floor(i / 3) - (rows - 1) / 2) * 22;
      paths.push({ d: unitWedge(x, y), fill: true });
    }
  }
  asiaGlyphs[`babylonian-${n}`] = {
    label: n === 0 ? 'Empty sexagesimal place' : `Babylonian sexagesimal digit ${n}`,
    paths,
    source: babylonianSource,
    provenance: 'original',
  };
}

